UPDATE "invitations" SET "teams" = (
  SELECT json_group_array("team") FROM (
    SELECT DISTINCT rt."team" AS "team" FROM json_each(CASE WHEN json_valid("invitations"."teams") THEN "invitations"."teams" ELSE '[]' END) j
    JOIN "_role_teams" rt ON rt."role" = j."value" WHERE rt."team" IS NOT NULL ORDER BY rt."team"
  )
)

UPDATE "tool_availability" SET "mode" = 'teams', "subjects" = (
  SELECT json_group_array("team") FROM (
    SELECT DISTINCT rt."team" AS "team" FROM json_each(CASE WHEN json_valid("tool_availability"."subjects") THEN "tool_availability"."subjects" ELSE '[]' END) j
    JOIN "_role_teams" rt ON rt."role" = j."value" WHERE rt."team" IS NOT NULL ORDER BY rt."team"
  )
) WHERE "mode" = 'roles'

