    SELECT DISTINCT rt."team" AS "team" FROM json_each(CASE WHEN json_valid("channel_access"."subjects") THEN "channel_access"."subjects" ELSE '[]' END) j
    JOIN "_role_teams" rt ON rt."role" = j."value" WHERE rt."team" IS NOT NULL ORDER BY rt."team"
  )
) WHERE "mode" = 'roles'
